const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin'}).format(new Date());
const KEY='acl-tech-demo-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))}catch{};
function initial(){return {issues:{0:[{text:'Beispiel: Auffälligkeit am Haubenverschluss – technische Bewertung steht aus.',date:today(),open:true}]},daily:{},winter:{},archive:[]}}
state=state||initial();let mode='daily',filter='all',query='',selected=3,step='issues',signature=false,pen=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Speichern fehlgeschlagen. Testdaten bitte exportieren.');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function issues(i){return (state.issues[i]||[]).filter(x=>x.open)}
function record(i){const k=today()+':'+i;return state.daily[k]||(state.daily[k]={checks:[],note:'',student:'',signed:null})}
function impact(x){return ['blocking','advisory','cosmetic'].includes(x.impact)?x.impact:'blocking'}
function blockers(i){return issues(i).filter(x=>impact(x)==='blocking')}
function status(i){return blockers(i).length?'red':record(i).signed?'green':'gray'}
function statusText(i){return {red:'UNKLAR',green:'KLAR',gray:'CHECK OFFEN'}[status(i)]}
function render(){ document.body.classList.toggle('daily-mode',mode==='daily');$('#dailyTab').classList.toggle('active',mode==='daily');$('#winterTab').classList.toggle('active',mode==='winter');mode==='daily'?renderDaily():renderWinter() }
function renderDaily(){const count=c=>DATA.fleet.filter((_,i)=>status(i)===c).length;$('#app').innerHTML=`<section class="fleet-overview"><div class="overview-head"><div><div class="eyebrow">Flugbetrieb / Tagesübersicht</div><h1>Unsere Flotte</h1></div><div class="overview-summary"><span class="badge green">${count('green')} KLAR</span><span class="badge red">${count('red')} UNKLAR</span><span class="badge">${count('gray')} CHECK OFFEN</span><span class="small muted">${new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeZone:'Europe/Berlin'}).format(new Date())}</span></div></div><div class="toolbar overview-toolbar">${[['all','Alle 8 Flugzeuge'],['gray','Check offen'],['red','Unklar'],['green','Klar']].map(([k,t])=>`<button class="${filter===k?'selected':''}" onclick="filter='${k}';renderDaily()">${t}</button>`).join('')}<input aria-label="Flugzeug suchen" placeholder="Flugzeug suchen …" value="${esc(query)}" oninput="query=this.value;renderCards()"></div><div class="grid fleet-grid" id="cards"></div><p class="overview-note">KLAR = heutige Kontrolle unterschrieben, keine sperrenden Mängel in der Demo. CHECK OFFEN = noch nicht bestätigt. UNKLAR = sperrender oder noch nicht bewerteter Mangel. <a href="#annualWork">↓ Arbeiten im laufenden Jahr</a></p></section><section id="annualWork" aria-label="Arbeiten im laufenden Jahr"></section>`;renderCards();renderAnnualWork()}
function renderCards(){$('#cards').innerHTML=DATA.fleet.map((f,i)=>({f,i})).filter(({f,i})=>(filter==='all'||status(i)===filter)&&(`${f.name} ${f.reg}`).toLowerCase().includes(query.toLowerCase())).map(({f,i})=>{const st=status(i),r=record(i),n=issues(i).length;return `<article class="card fleet-card status-${st}"><button class="aircraft-open" onclick="openDaily(${i})" aria-label="${esc(f.name)}: ${statusText(i)}"><div class="fleet-status"><span>${st==='red'?'!':st==='green'?'✓':'○'}</span> ${statusText(i)}</div><div class="photo"><img src="${f.img}" alt="${esc(f.name)} des Aero-Clubs Langenselbold"></div><div class="cardbody"><div class="cardline"><h3>${f.name}</h3><span class="reg">${f.reg==='Kennzeichen ergänzen'?'':f.reg}</span></div><div class="cardnote" title="${esc(n?issues(i)[0].text:'')}">${n?`${blockers(i).length?blockers(i).length+' sperrend · ':''}${issues(i).filter(x=>impact(x)==='advisory').length} Piloteninfo · ${issues(i).filter(x=>impact(x)==='cosmetic').length} weitere`:r.signed?`Unterschrieben · ${esc(r.signed.name)} · ${r.signed.time}`:r.checks.some(Boolean)?`${r.checks.filter(Boolean).length}/24 Punkte · Unterschrift fehlt`:i===3?'Tageskontrolle starten →':'Checkliste noch ergänzen'}</div></div></button><button class="quick-check ${i===3&&!r.signed?'primary':''}" onclick="startDaily(${i})" ${i!==3?'disabled':''}>${r.signed?'✓ Tageskontrolle bestätigt':i!==3?'Checkliste folgt':r.checks.some(Boolean)?'Vorflugkontrolle fortsetzen →':'Vorflugkontrolle starten →'}</button></article>`}).join('')||'<p class="empty">Kein passendes Flugzeug.</p>'}
function showDialog(title,sub,body,foot=''){$('#dialogContent').innerHTML=`<div class="dhead"><div><div class="eyebrow">${sub}</div><h2>${title}</h2></div><div class="header-actions">${sub==='Flugbetrieb'&&['checks','sign'].includes(step)?'<button class="report-always" onclick="openIssueReport()">＋ Mangel melden</button>':''}<button aria-label="Schließen" onclick="closeDialog()">✕</button></div></div><div class="dbody">${body}</div>${foot?`<div class="dfoot">${foot}</div>`:''}`;if(!$('#detail').open)$('#detail').showModal()}
function closeDialog(){$('#detail').close();render()}
function openDaily(i){workView=null;selected=i;issueDraft={text:'',category:'Unklar / Sonstiges',location:'',priority:'Bewertung erforderlich',impact:'blocking',photos:[]};step='issues';drawDaily()}
function startDaily(i){openDaily(i);if(i===3&&!record(i).signed){step='checks';drawDaily()}}
function checkWarnings(){const entries=issues(selected).filter(x=>impact(x)!=='cosmetic');return entries.length?`<details class="check-alerts" open><summary>Vor dem Flug beachten: ${blockers(selected).length} sperrend · ${entries.filter(x=>impact(x)==='advisory').length} Pilotenhinweise</summary>${entries.map(x=>`<div class="check-alert ${impact(x)}"><strong>${impactLabels[impact(x)]}</strong><p>${esc(x.text)}</p></div>`).join('')}</details>`:''}
function drawDaily(){const i=selected,f=DATA.fleet[i],r=record(i);let body='',foot='';if(step==='issues'){
 const list=issues(i).map((x,k)=>({x,k})),blocking=list.filter(({x})=>impact(x)==='blocking'),advisory=list.filter(({x})=>impact(x)==='advisory'),other=list.filter(({x})=>impact(x)==='cosmetic');
 body=`<div class="aircraft-status ${status(i)}"><strong>${statusText(i)}</strong><span>${blockers(i).length?'Sperrender Mangel / Bewertung ausstehend':r.signed?'Heutige Kontrolle unterschrieben':'Heutige Kontrolle noch offen'}</span></div><div class="issue-summary"><span class="badge red">${blocking.length} sperrend</span><span class="badge pilot-badge">${advisory.length} Pilotenhinweise</span><span class="badge">${other.length} weitere</span></div>${blocking.length?`<h3 class="sectiontitle">Sperrende Mängel</h3>${blocking.map(({x,k})=>issueCard(x,k)).join('')}`:''}${advisory.length?`<h3 class="sectiontitle">Wichtig für den Piloten</h3>${advisory.map(({x,k})=>issueCard(x,k)).join('')}`:''}${!blocking.length&&!advisory.length?'<div class="info">Keine sperrenden Mängel oder wichtigen Pilotenhinweise hinterlegt.</div>':''}<details class="additional-issues"><summary>Weitere Mängel / Lackschäden (${other.length})</summary>${other.length?other.map(({x,k})=>issueCard(x,k)).join(''):'<p class="muted small">Keine weiteren Mängel hinterlegt.</p>'}</details>${i!==3?'<p class="muted small">Die Tagescheckliste für dieses Flugzeug wird noch ergänzt.</p>':''}${r.signed?`<p class="small muted">Heute bestätigt: ${esc(r.signed.name)} · ${r.signed.time}</p>`:''}`;
 foot=`<button onclick="openIssueReport()">＋ Neuen Mangel melden</button><button class="primary" ${i!==3||r.signed?'disabled':''} onclick="step='checks';drawDaily()">${r.checks.some(Boolean)?'Tageskontrolle fortsetzen':'Tageskontrolle starten'} →</button>`;
 }
if(step==='checks'){let n=0;body=`<div class="eyebrow">02 / Tageskontrolle</div><div id="checkWarnings">${checkWarnings()}</div><div class="links"><a href="assets/daily-ls4.pdf" target="_blank">Originalcheckliste ↗</a><span>Rev. 1.0 · 25.05.2020</span></div><p class="info">Originalinhalt übernommen. Eingaben bleiben beim Schließen lokal erhalten.</p>${DATA.daily.map(g=>`<div class="sectiontitle">${g.title}</div>${g.items.map(t=>{const k=n++;return `<div class="row"><input type="checkbox" id="check-${k}" ${r.checks[k]?'checked':''} onchange="record(selected).checks[${k}]=this.checked;save();updateCount()"><label for="check-${k}">${esc(t)}</label></div>`}).join('')}`).join('')}<div class="fields"><label>Flugschüler / ausführende Person<input value="${esc(r.student)}" onchange="record(selected).student=this.value;save()" placeholder="Name"></label></div><label>Beanstandungen / Bemerkungen<textarea onchange="record(selected).note=this.value;save()" placeholder="Beanstandungen zusätzlich als Mangel erfassen">${esc(r.note)}</textarea></label><button onclick="openIssueReport()">Mangel erfassen</button>`;foot=`<span id="checkCount"></span><button class="primary" id="toSign" onclick="step='sign';drawDaily()">Zur Bestätigung →</button>`}
if(step==='sign'){body=`<div class="eyebrow">03 / Persönlicher Abschluss</div><h2>Kontrolle bestätigen</h2><div id="checkWarnings">${checkWarnings()}</div><p>${r.checks.filter(Boolean).length} von 24 Punkten erledigt. ${blockers(i).length?'Sperrende Mängel halten den Flugzeugstatus weiterhin rot.':''}</p><div class="info">Demo: Die PIN 1234 prüft nur den Ablauf. Es findet noch keine echte Identitätsprüfung statt.</div><div class="fields"><label>Fluglehrer / bestätigende Person<input id="signer" autocomplete="off" placeholder="Vor- und Nachname"></label><label>Demo-PIN<input id="pin" type="password" inputmode="numeric" placeholder="1234" autocomplete="off"></label></div><label>Unterschrift mit Finger oder Stift<canvas id="sig" class="signature" width="900" height="240"></canvas></label><button onclick="clearSig()">Unterschrift löschen</button>`;foot=`<button onclick="step='checks';drawDaily()">← Zurück</button><button class="primary" onclick="signRecord()">Testprotokoll unterschreiben</button>`}
showDialog(`${f.name} · ${f.reg}`,'Flugbetrieb',body,foot);if(step==='checks')updateCount();if(step==='sign')setupSig()}
function updateCount(){const n=record(selected).checks.filter(Boolean).length;$('#checkCount').textContent=`${n} / 24 erledigt · lokal gespeichert`;$('#toSign').disabled=n!==24}
let issueDraft={text:'',category:'Unklar / Sonstiges',location:'',priority:'Bewertung erforderlich',impact:'blocking',photos:[]},photoBusy=false;
const categories=['Lack / Oberfläche','Struktur / Riss / Verformung','Steuerung / Ruder','Fahrwerk / Bremse','Haube / Cockpit','Instrumente / Elektrik','Antrieb','Unklar / Sonstiges'];
const priorities=['Bewertung erforderlich','Zeitnah bearbeiten','Dringend prüfen'];
const impactLabels={blocking:'Sperrend / Flugzeug unklar',advisory:'Wichtiger Pilotenhinweis',cosmetic:'Weitere Mängel / Lackschäden'};
function impactOptions(value){return Object.entries(impactLabels).map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}
function issueForm(){return `<div class="fields"><label>Bedeutung für den Flugbetrieb<select id="issueImpact" onchange="issueDraft.impact=this.value">${impactOptions(issueDraft.impact||'blocking')}</select></label><label>Kategorie<select id="issueCategory" onchange="issueDraft.category=this.value">${categories.map(t=>`<option ${t===issueDraft.category?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Dringlichkeit der Meldung<select id="issuePriority" onchange="issueDraft.priority=this.value">${priorities.map(t=>`<option ${t===issueDraft.priority?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Position / Bauteil<input id="issueLocation" placeholder="z. B. linker Flügel, Unterseite am Randbogen" value="${esc(issueDraft.location)}" oninput="issueDraft.location=this.value"></label></div><label>Beschreibung<textarea id="issueText" placeholder="Was ist aufgefallen? Größe und Aussehen des Schadens beschreiben." oninput="issueDraft.text=this.value">${esc(issueDraft.text)}</textarea></label><div class="sectiontitle">Fotos zum Mangel</div><p class="small muted">Bei Lackschäden am besten eine Übersicht und eine Nahaufnahme. Bis zu 4 Fotos pro Meldung.</p><div class="photo-actions"><button onclick="$('#cameraInput').click()">Foto aufnehmen</button><button onclick="$('#galleryInput').click()">Bilder auswählen</button><input hidden id="cameraInput" type="file" accept="image/*" capture="environment" onchange="addPhotos(this)"><input hidden id="galleryInput" type="file" accept="image/*" multiple onchange="addPhotos(this)"></div><div id="draftPhotos" class="issue-photos">${draftPhotosHTML()}</div><p id="photoStatus" role="status" class="small muted"></p><p class="small muted">Die Bedeutung steuert den Status: sperrend macht das Flugzeug unklar; Pilotenhinweise bleiben sichtbar; weitere Mängel erscheinen aufklappbar. Nicht bewertete Meldungen gelten zunächst als sperrend.</p><div class="create-work-from-report"><label><input type="checkbox" ${issueDraft.createWork?'checked':''} onchange="issueDraft.createWork=this.checked;$('#reportWorkFields').hidden=!this.checked"> Arbeit im laufenden Jahr zu diesem Mangel anlegen</label><div id="reportWorkFields" ${issueDraft.createWork?'':'hidden'}><label>Titel der Arbeit<input value="${esc(issueDraft.workTitle||'')}" placeholder="z. B. Lackschaden am linken Flügel ausbessern" oninput="issueDraft.workTitle=this.value"></label><p class="small muted">Die Beschreibung und der Verweis auf die Schadensfotos werden übernommen.</p></div></div><button id="saveIssue" class="primary" onclick="addIssue()">Mangel mit Fotos speichern</button>`}
function draftPhotosHTML(){return issueDraft.photos.map((p,k)=>`<figure><img src="${p.data}" alt="Foto ${k+1} zum neuen Mangel"><button aria-label="Foto ${k+1} entfernen" onclick="issueDraft.photos.splice(${k},1);$('#draftPhotos').innerHTML=draftPhotosHTML()">✕ Entfernen</button></figure>`).join('')}
function issueCard(x,k){const level=impact(x);return `<div class="issue issue-${level}"><strong>${impactLabels[level]} · ${esc(x.date)}</strong><div class="issue-tags"><span class="badge">${esc(x.category||'Nicht klassifiziert')}</span><span class="badge">${esc(x.priority||'Bewertung erforderlich')}</span></div>${x.location?`<div class="small"><b>Position:</b> ${esc(x.location)}</div>`:''}<p>${esc(x.text)}</p><div class="issue-photos">${(x.photos||[]).map((p,j)=>`<button class="photo-thumb" onclick="viewIssuePhoto(${k},${j})" aria-label="Schadensfoto ${j+1} vergrößern"><img src="${p.data}" alt="Schadensfoto ${j+1}"></button>`).join('')}</div>${x.workId?`<span class="badge green">✓ Zusätzliche Arbeit erfasst</span>`:`<button class="small" onclick="workFromIssue(${k})">＋ Arbeit aus diesem Mangel</button>`}<details class="classification"><summary>Einstufung ändern</summary><label class="small">Bedeutung für den Flugbetrieb<select aria-label="Einstufung des Mangels ändern" onchange="updateImpact(${k},this.value)">${impactOptions(level)}</select></label><span class="small muted">Demo-Einstufung</span></details></div>`}
function updateImpact(k,value){if(!Object.hasOwn(impactLabels,value))return;const x=issues(selected)[k],old=x.impact;x.impact=value;if(!save()){x.impact=old;return}drawDaily();render();toast('Einstufung gespeichert')}
function viewIssuePhoto(k,j){const x=issues(selected)[k],p=x.photos[j];$('#photoViewContent').innerHTML=`<div class="dhead"><div><h2>Schadensfoto ${j+1}</h2><span class="small">${esc(x.location||x.category||'Mangel')}</span></div><button onclick="$('#photoView').close()" aria-label="Foto schließen">✕</button></div><img class="full-photo" src="${p.data}" alt="Vergrößertes Schadensfoto"><p style="padding:0 20px">${esc(x.text)}</p>`;$('#photoView').showModal()}
async function compressPhoto(file){if(!file.type.startsWith('image/'))throw Error('Bitte eine Bilddatei auswählen.');if(file.size>25*1024*1024)throw Error('Das Bild ist größer als 25 MB.');const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();const scale=Math.min(1,1400/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(im.naturalWidth*scale);c.height=Math.round(im.naturalHeight*scale);const ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);return {name:file.name,data:c.toDataURL('image/jpeg',.72)}}catch(e){throw Error('Bild konnte nicht gelesen werden. Bitte JPEG, PNG oder WebP verwenden.')}finally{URL.revokeObjectURL(url)}}
async function addPhotos(input){if(photoBusy)return;photoBusy=true;const draft=issueDraft,files=Array.from(input.files||[]),messages=[];const saveButton=$('#saveIssue');if(saveButton)saveButton.disabled=true;$('#photoStatus').textContent='Fotos werden vorbereitet …';try{for(const f of files){if(draft.photos.length>=4){messages.push('Maximal 4 Fotos pro Meldung.');break}try{const photo=await compressPhoto(f);draft.photos.push(photo)}catch(e){messages.push(e.message)}}}finally{photoBusy=false;input.value='';if(draft===issueDraft&&$('#draftPhotos')){$('#draftPhotos').innerHTML=draftPhotosHTML();$('#photoStatus').textContent=messages.join(' ')||`${draft.photos.length} Foto(s) hinzugefügt.`;$('#saveIssue').disabled=false}}}
function openIssueReport(){if(photoBusy){toast('Fotos werden noch vorbereitet. Bitte kurz warten.');return}const aircraft=DATA.fleet[selected];$('#reportContent').innerHTML=`<div class="dhead"><div><div class="eyebrow">${aircraft.name} · ${aircraft.reg}</div><h2>Mangel melden</h2></div><button aria-label="Zur Kontrolle zurück" onclick="$('#reportDialog').close()">✕</button></div><div class="dbody">${issueForm()}</div><div class="dfoot"><button onclick="$('#reportDialog').close()">← ${step==='checks'||step==='sign'?'Zur Kontrolle':'Zum Flugzeug'}</button><span class="small muted">Deine bisherigen Eingaben bleiben erhalten.</span></div>`;$('#reportDialog').showModal()}
function addIssue(){if(photoBusy){toast('Bitte warten, bis die Fotos geladen sind.');return}const t=issueDraft.text.trim();if(!t){toast('Bitte den Mangel beschreiben.');return}const list=state.issues[selected]??=[],issue={id:newId(),text:t,date:today(),open:true,impact:issueDraft.impact||'blocking',category:issueDraft.category,location:issueDraft.location.trim(),priority:issueDraft.priority,photos:issueDraft.photos.map(p=>({...p}))};list.push(issue);let work=null;if(issueDraft.createWork){work=makeCustomWork(issueDraft.workTitle?.trim()||'Befund beheben: '+t.slice(0,90),t,'Zusätzliche Arbeiten',issue.id,null,{scope:'annual',year:Number(issue.date.slice(0,4))});customWorks(selected).push(work);issue.workId=work.id}if(!save()){list.pop();if(work)customWorks(selected).pop();toast('Speichern fehlgeschlagen. Meldung und Arbeit wurden nicht übernommen.');return}issueDraft={text:'',category:'Unklar / Sonstiges',location:'',priority:'Bewertung erforderlich',impact:'blocking',photos:[]};if($('#reportDialog').open)$('#reportDialog').close();if(step==='issues')drawDaily();else if($('#checkWarnings'))$('#checkWarnings').innerHTML=checkWarnings();render();toast(work?'Mangel und zusätzliche Arbeit gespeichert':'Mangel gespeichert · Kontrolle kann fortgesetzt werden')}
function setupSig(){signature=false;const c=$('#sig'),ctx=c.getContext('2d');ctx.strokeStyle='#123c35';ctx.lineWidth=3;ctx.lineCap='round';const pt=e=>{let b=c.getBoundingClientRect();return [(e.clientX-b.left)*c.width/b.width,(e.clientY-b.top)*c.height/b.height]};c.onpointerdown=e=>{pen=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...pt(e))};c.onpointermove=e=>{if(!pen)return;signature=true;ctx.lineTo(...pt(e));ctx.stroke()};c.onpointerup=c.onpointercancel=()=>pen=false}
function clearSig(){$('#sig').getContext('2d').clearRect(0,0,900,240);signature=false}
function signRecord(){const name=$('#signer').value.trim();if(!name||$('#pin').value!=='1234'||!signature){toast('Name, Demo-PIN 1234 und Unterschrift erforderlich.');return}const r=record(selected);if(r.checks.filter(Boolean).length!==24)return;const signed={name,time:new Intl.DateTimeFormat('de-DE',{timeStyle:'short',timeZone:'Europe/Berlin'}).format(new Date()),date:today(),image:$('#sig').toDataURL()};r.signed=signed;state.archive.push({aircraft:DATA.fleet[selected].name,revision:'1.0 / 25.05.2020',...JSON.parse(JSON.stringify(r))});if(save()){closeDialog();toast('Testprotokoll gespeichert')}}
const groups=['Flügel','Rumpf','Höhenleitwerk','Anhänger'];
function task(i,k){return state.winter[i+':'+k]||(state.winter[i+':'+k]={stage:'open',by:'',note:'',verifiedBy:''})}
function annualYear(){return Number(state.annualYear)||Number(today().slice(0,4))}
function workItems(i,scope='winter',year=annualYear()){const standard=scope==='winter'&&i===3?expanded().map((t,k)=>({...t,key:k,scope:'winter'})):[];const wax=scope==='annual'?[{key:'annual:wax:'+year,title:'Im laufenden Jahr erneut wachsen',text:'Flugzeug zusätzlich zur Winterwartung im laufenden Jahr wachsen. Durchführung bis zum 30. Juni dokumentieren.',group:'Jährliche Pflege',scope:'annual',year,dueDate:year+'-06-30'}]:[];const custom=(state.customWork?.[i]||[]).filter(t=>(t.scope||'winter')===scope&&(scope!=='annual'||Number(t.year)===Number(year))).map(t=>({...t,scope:t.scope||'winter',key:'custom:'+t.id}));return [...standard,...wax,...custom]}
function findWorkItem(i,k){if(typeof k==='number')return workItems(i,'winter').find(t=>t.key===k);if(k.startsWith('annual:wax:'))return workItems(i,'annual',Number(k.split(':')[2])).find(t=>t.key===k);const t=(state.customWork?.[i]||[]).find(t=>'custom:'+t.id===k);return t?{...t,scope:t.scope||'winter',key:k}:null}
function workProgress(i,scope='winter',year=annualYear()){const items=workItems(i,scope,year),total=items.length;let done=0,checked=0,active=0,units=0;items.forEach(t=>{const r=task(i,t.key);if(r.stage==='checked'){checked++;done++;units+=100}else if(r.stage==='done'){done++;units+=100}else if(r.stage==='work'){active++;units+=Math.max(0,Math.min(99,Number(r.percent)||0))}});return {total,done,checked,active,workedPct:total?Math.round(units/total):0,donePct:total?Math.round(done/total*100):0,checkedPct:total?Math.round(checked/total*100):0}}
function progress(i){return workProgress(i).checkedPct}
function newId(){return Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)}
let workView=null,workDraft=null,workFormReturn=null;
function customWorks(i){if(!state.customWork)state.customWork={};return state.customWork[i]||(state.customWork[i]=[])}
function makeCustomWork(title,text,group='Zusätzliche Arbeiten',sourceIssueId=null,sourceTaskKey=null,options={}){return {scope:options.scope||'winter',year:options.year||annualYear(),dueDate:options.dueDate||'',id:newId(),title:title.trim(),text:text.trim(),group:group.trim()||'Zusätzliche Arbeiten',sourceIssueId,sourceTaskKey,createdAt:new Date().toISOString()}}

function expanded(){return DATA.winter.flatMap(t=>t.group==='Flügel'?[{...t,title:t.title+' · links'},{...t,title:t.title+' · rechts'}]:[t])}
const DAY=86400000;
function winterFleet(){return DATA.fleet.map((_,i)=>i).filter(i=>DATA.fleet[i].name!=='Dynamic WT9')}
function planning(){const eligible=winterFleet();if(!state.planning)state.planning={order:[...eligible],overlap:2,year:2026};const p=state.planning;p.order=[...new Set((p.order||[]).filter(i=>Number.isInteger(i)&&eligible.includes(i)))];eligible.forEach(i=>{if(!p.order.includes(i))p.order.push(i)});p.overlap=Math.max(0,Math.min(5,Math.round(Number(p.overlap)||0)));if(!p.startDate)p.startDate=`${p.year}-11-01`;if(!p.endDate)p.endDate=`${p.year+1}-03-31`;return p}
function dateMS(value){return Date.parse(value+'T00:00:00Z')}
function isoDate(ms){return new Date(ms).toISOString().slice(0,10)}
function schedule(){const p=planning(),start=dateMS(p.startDate),end=dateMS(p.endDate)+DAY,days=(end-start)/DAY,n=p.order.length,total=days+p.overlap*(n-1),viewStart=Math.min(Date.UTC(p.year,9,1),Date.UTC(new Date(start).getUTCFullYear(),new Date(start).getUTCMonth(),1)),endDate=new Date(end-DAY),viewEnd=Math.max(Date.UTC(p.year+1,4,1),Date.UTC(endDate.getUTCFullYear(),endDate.getUTCMonth()+1,1)),viewDays=(viewEnd-viewStart)/DAY;return {start,end,days,viewStart,viewEnd,viewDays,rows:p.order.map((i,k)=>{const from=Math.round(k*total/n)-k*p.overlap,to=Math.round((k+1)*total/n)-k*p.overlap;return {i,from,to,start:start+from*DAY,end:start+to*DAY}})}}
function calendarMonths(plan){const months=[];for(let ms=plan.viewStart;ms<plan.viewEnd;){const d=new Date(ms),m=d.getUTCMonth(),next=Date.UTC(d.getUTCFullYear(),m+1,1);months.push({start:ms,end:next,label:['JAN','FEB','MÄR','APR','MAI','JUN','JUL','AUG','SEP','OKT','NOV','DEZ'][m],reserve:m===9||m===3,left:(ms-plan.viewStart)/DAY/plan.viewDays*100,width:(next-ms)/DAY/plan.viewDays*100});ms=next}return months}
function monthBackground(plan){return calendarMonths(plan).map(m=>`<span aria-hidden="true" class="month-grid ${m.reserve?'reserve-month':''}" style="left:${m.left}%;width:${m.width}%"></span>`).join('')}
function applyPlanningPeriod(startValue,endValue){const start=dateMS(startValue),end=dateMS(endValue),p=planning();if(!startValue||!endValue||!Number.isFinite(start)||!Number.isFinite(end)||end<start){toast('Bitte einen gültigen Beginn und ein späteres Ende wählen.');return false}const days=(end-start)/DAY+1,minDays=p.order.length*(p.overlap+1)+p.overlap;if(days<minDays){toast(`Für sieben Flugzeuge und ${p.overlap} Tage Überschneidung sind mindestens ${minDays} Kalendertage nötig.`);return false}if(days>366){toast('Bitte einen Wartungszeitraum von höchstens einem Jahr wählen.');return false}const old={startDate:p.startDate,endDate:p.endDate,year:p.year};p.startDate=startValue;p.endDate=endValue;const d=new Date(start);p.year=d.getUTCMonth()>=6?d.getUTCFullYear():d.getUTCFullYear()-1;if(!save()){Object.assign(p,old);return false}renderWinter();toast('Zeitraum und Flugzeugtermine aktualisiert');return true}
function resetPlanningPeriod(){const p=planning();applyPlanningPeriod(`${p.year}-11-01`,`${p.year+1}-03-31`)}
function shortDate(ms){return new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'2-digit',timeZone:'UTC'}).format(new Date(ms))}
function planDate(){return state.planningDate||today()}
function setOverlap(v){const p=planning(),value=Number(v),days=(dateMS(p.endDate)-dateMS(p.startDate))/DAY+1;if(days<p.order.length*(value+1)+value){toast('Für diese Überschneidung ist der Zeitraum zu kurz.');renderWinter();return}const old=p.overlap;p.overlap=value;if(!save()){p.overlap=old;return}renderWinter()}
function moveAircraft(from,to){const p=planning();if(from===to||from<0||to<0||from>=p.order.length||to>=p.order.length)return;const old=[...p.order];p.order.splice(to,0,p.order.splice(from,1)[0]);if(!save()){p.order=old;return}renderWinter();toast('Reihenfolge und Zeiträume aktualisiert')}
let dragging=null;
function startReorder(e,k){if(e.button!==0)return;e.preventDefault();dragging={from:k,to:k,y:e.clientY,moved:false};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.classList.add('dragging')}
function updateReorder(e){if(!dragging)return;if(Math.abs(e.clientY-dragging.y)<6&&!dragging.moved)return;dragging.moved=true;const rows=[...document.querySelectorAll('.plan-row')];let best=dragging.from,distance=Infinity;rows.forEach((row,k)=>{const b=row.getBoundingClientRect(),d=Math.abs(e.clientY-(b.top+b.height/2));if(d<distance){distance=d;best=k}row.classList.remove('drop-target')});dragging.to=best;rows[best]?.classList.add('drop-target')}
function finishReorder(e){if(!dragging)return;const d=dragging;dragging=null;e.currentTarget.classList.remove('dragging');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));if(d.moved)moveAircraft(d.from,d.to)}
let weekendOffset=0;
function nextWeekend(reference=today(),offset=weekendOffset){const base=dateMS(reference),day=new Date(base).getUTCDay(),start=base+((6-day+7)%7+offset*7)*DAY;return {start,end:start+2*DAY,saturday:isoDate(start),sunday:isoDate(start+DAY)}}
function weekendWork(reference=today(),offset=weekendOffset){const weekend=nextWeekend(reference,offset),plan=schedule(),year=new Date(weekend.start).getUTCFullYear(),rows=[];DATA.fleet.forEach((f,i)=>{if(!winterFleet().includes(i))return;const slot=plan.rows.find(r=>r.i===i),scheduled=slot&&slot.start<weekend.end&&slot.end>weekend.start,overdue=slot&&slot.end<=weekend.start;const candidates=[...(slot?workItems(i,'winter'):[]),...workItems(i,'annual',year)];const items=candidates.map(t=>({t,r:task(i,t.key)})).filter(({t,r})=>{if(r.stage==='checked')return false;if(r.plannedDate)return dateMS(r.plannedDate)<weekend.end;if(t.scope==='annual')return false;return scheduled||overdue||r.stage==='work'||r.stage==='done'});items.sort((a,b)=>{const rank=x=>{const issue=x.t.sourceIssueId?(state.issues[i]||[]).find(y=>y.id===x.t.sourceIssueId):null;return issue?.open&&impact(issue)==='blocking'?0:x.r.stage==='done'?1:x.r.stage==='work'?2:3};return rank(a)-rank(b)});if(scheduled||items.length)rows.push({i,slot,scheduled:!!scheduled,overdue:!!overdue,items})});rows.sort((a,b)=>Number(b.scheduled)-Number(a.scheduled)||(plan.rows.findIndex(r=>r.i===a.i)-plan.rows.findIndex(r=>r.i===b.i)));return {weekend,rows}}
function weekendTaskHTML(i,{t,r}){return `<div class="weekend-task"><div><strong>${esc(t.title)}</strong><div class="small muted">${esc(t.group)} · ${t.scope==='annual'?'Jahresarbeit':'Winterwartung'}</div></div><span class="badge ${r.stage==='done'?'gold':''}">${{open:'Offen',work:'Fortsetzen · '+(Number(r.percent)||0)+'%',done:'Prüfung offen'}[r.stage]||'Offen'}</span><button onclick="openAnnualTask(${i},${esc(JSON.stringify(t.key))})">Öffnen →</button></div>`}
function weekendHTML(){const {weekend,rows}=weekendWork(),total=rows.reduce((n,row)=>n+row.items.length,0),plan=schedule();return `<section class="panel weekend-panel"><div class="top"><div><div class="eyebrow">${weekendOffset?'Wochenendvorschau':'Nächstes Wochenende'}</div><h2>${shortDate(weekend.start)} – ${shortDate(weekend.end-DAY)}${new Date(weekend.start).getUTCFullYear()}</h2><p class="small muted">${total} offene Arbeiten · ${rows.filter(r=>r.scheduled).length} Flugzeug(e) im Planzeitraum</p></div><div class="weekend-nav"><button aria-label="Vorheriges Wochenende" ${weekendOffset===0?'disabled':''} onclick="weekendOffset=Math.max(0,weekendOffset-1);renderWinter()">←</button><button onclick="weekendOffset=0;renderWinter()">Nächstes Wochenende</button><button aria-label="Folgendes Wochenende" onclick="weekendOffset++;renderWinter()">→</button></div></div><p class="small muted">Aus dem Flugzeugplan abgeleitet. Begonnene Arbeiten und ausstehende Prüfungen bleiben sichtbar. Einzelne Arbeiten können über „Geplant für“ ausdrücklich einem Wochenende zugeordnet werden.</p>${!rows.length?`<div class="info">Für dieses Wochenende sind keine Winterarbeiten vorgesehen.${weekend.end<=plan.start?' Wartungsbeginn: '+shortDate(plan.start)+new Date(plan.start).getUTCFullYear()+'.':''}</div>`:rows.map(row=>`<div class="weekend-aircraft"><div class="top"><div><h3>${DATA.fleet[row.i].name}</h3><span class="badge ${row.overdue?'gold':''}">${row.scheduled?'Laut Winterplan an der Reihe':row.overdue?'Offene Arbeiten aus früherem Zeitraum':'Vorgemerkt / in Bearbeitung'}</span></div><button onclick="openWinter(${row.i})">Alle Arbeiten →</button></div>${row.items.length?row.items.slice(0,5).map(item=>weekendTaskHTML(row.i,item)).join(''):(workItems(row.i).length?'<p class="small muted">Keine offenen Arbeiten für dieses Wochenende. Bereits geprüfte Arbeiten sind ausgeblendet.</p>':'<p class="small muted">Für dieses Flugzeug sind noch keine Wartungsarbeiten hinterlegt.</p>')}${row.items.length>5?`<details class="weekend-more"><summary>Weitere ${row.items.length-5} offene Arbeiten</summary>${row.items.slice(5).map(item=>weekendTaskHTML(row.i,item)).join('')}</details>`:''}</div>`).join('')}</section>`}
function renderWinter(){const p=planning(),plan=schedule(),date=Date.parse(planDate()+'T00:00:00Z'),offset=(date-plan.start)/DAY,line=date>=plan.viewStart&&date<plan.viewEnd?(date-plan.viewStart)/DAY/plan.viewDays*100:null;$('#app').innerHTML=`<div class="top"><div><div class="eyebrow">Winterwartung / Saison ${p.year}–${String(p.year+1).slice(2)}</div><h1>Nacheinander durch den Winter.</h1><p class="muted">Sieben Segelflugzeuge – die Zeiträume passen sich der Reihenfolge an.</p></div><div class="winter-top-actions"><button class="primary" onclick="openWorkForm()">＋ Arbeit hinzufügen</button><span class="badge">${shortDate(plan.start)}${new Date(plan.start).getUTCFullYear()} – ${shortDate(plan.end-DAY)}${new Date(plan.end-DAY).getUTCFullYear()}</span></div></div>${weekendHTML()}<div class="panel"><div class="top"><div><h2>Winterfahrplan</h2><p class="muted small">Am Griff ziehen oder mit ↑ / ↓ verschieben. Die verfügbare Zeit wird gleichmäßig verteilt.</p></div><div class="legend"><span><b></b>Geplanter Zeitraum</span><span><b class="worked"></b>Bearbeitet</span><span><b class="actual"></b>Geprüft / abgeschlossen</span></div></div><details class="plan-settings"><summary>⚙ Planung einstellen</summary><div class="period-controls"><label>Wartungsbeginn<input id="planningStart" type="date" value="${p.startDate}"></label><label>Wartungsende einschließlich<input id="planningEnd" type="date" value="${p.endDate}"></label><button class="primary" onclick="applyPlanningPeriod($('#planningStart').value,$('#planningEnd').value)">Zeitraum übernehmen</button><button onclick="resetPlanningPeriod()">Standard: November – März</button></div><p class="small muted">Oktober und April sind schattierte Randmonate. Regulär wird nur von November bis März geplant; ein abweichender Zeitraum lässt sich ausdrücklich einstellen.</p>${plan.start<Date.UTC(p.year,10,1)||plan.end>Date.UTC(p.year+1,3,1)?'<p class="period-exception">Abweichender Zeitraum: Die Planung nutzt Tage außerhalb von November bis März.</p>':''}<div class="plan-controls"><label>Überschneidung zwischen zwei Flugzeugen<select aria-label="Überschneidung in Tagen" onchange="setOverlap(this.value)">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${n===p.overlap?'selected':''}>${n===0?'Keine Überschneidung':n+' Tage · Werkstatt / Nebenraum'}</option>`).join('')}</select></label><label>Stichtag für Soll / Ist<input type="date" value="${planDate()}" onchange="if(this.value){state.planningDate=this.value;save();renderWinter()}"></label><button onclick="delete state.planningDate;save();renderWinter()">Heute</button></div></details><div class="gantt"><div class="timeline sequential"><div class="ghead"><span>REIHENFOLGE / FLUGZEUG</span><div class="calendar-months">${calendarMonths(plan).map(m=>`<span class="${m.reserve?'reserve-header':''}" style="left:${m.left}%;width:${m.width}%">${m.label}${m.reserve?'<small>Randmonat</small>':''}</span>`).join('')}</div><span>FORTSCHRITT</span></div>${plan.rows.map((row,k)=>{const f=DATA.fleet[row.i],wp=workProgress(row.i),progressValue=wp.workedPct,expected=Math.max(0,Math.min(100,Math.round((offset-row.from)/(row.to-row.from)*100))),late=progressValue<expected;return `<div class="grow plan-row" data-order="${k}"><div class="plan-name"><div class="reorder-controls"><button class="drag-handle" aria-label="${esc(f.name)} verschieben; Pfeiltasten nach oben oder unten" onpointerdown="startReorder(event,${k})" onpointermove="updateReorder(event)" onpointerup="finishReorder(event)" onpointercancel="dragging=null;renderWinter()" onkeydown="if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();moveAircraft(${k},${k}+(event.key==='ArrowUp'?-1:1))}">⠿</button><div><button aria-label="${esc(f.name)} nach oben" ${k===0?'disabled':''} onclick="moveAircraft(${k},${k-1})">↑</button><button aria-label="${esc(f.name)} nach unten" ${k===plan.rows.length-1?'disabled':''} onclick="moveAircraft(${k},${k+1})">↓</button></div></div><button class="gname" onclick="openWinter(${row.i})"><span class="order-number">${k+1}.</span> ${f.name}<div class="reg">${shortDate(row.start)} – ${shortDate(row.end-DAY)} · ${row.to-row.from} Tage</div></button></div><div class="track">${monthBackground(plan)}${line!==null?`<div class="today" style="left:${line}%"></div>`:''}<div class="bar" style="left:${(row.start-plan.viewStart)/DAY/plan.viewDays*100}%;width:${(row.to-row.from)/plan.viewDays*100}%"></div><div class="bar worked" style="left:${(row.start-plan.viewStart)/DAY/plan.viewDays*100}%;width:${(row.to-row.from)/plan.viewDays*progressValue}%"></div><div class="bar actual verified" style="left:${(row.start-plan.viewStart)/DAY/plan.viewDays*100}%;width:${(row.to-row.from)/plan.viewDays*wp.checkedPct}%"></div>${wp.active?`<span class="working-marker" title="${wp.active} Arbeit(en) in Bearbeitung" style="left:${(row.start-plan.viewStart)/DAY/plan.viewDays*100}%"></span>`:''}</div><div class="gstatus"><strong>${progressValue}% bearbeitet</strong><span>${wp.checkedPct}% geprüft · Soll ${expected}%</span><span class="activity-text">${wp.active?wp.active+' in Arbeit · ':''}${wp.done}/${wp.total} durchgeführt</span></div></div>`}).join('')}</div></div><p class="small muted">${line===null?(offset<0?'Stichtag liegt vor dem Wartungsbeginn.':'Stichtag liegt nach dem Saisonende.'):'Senkrechte Linie: gewählter Stichtag.'} ${p.overlap?`Nur aufeinanderfolgende Flugzeuge überschneiden sich um ${p.overlap} Tage.`:'Jedes Flugzeug beginnt direkt nach dem vorherigen.'} Soll: gleichmäßiger Fortschritt im jeweiligen Zeitraum. Orange: bearbeiteter Anteil einschließlich eingetragenem Teilfortschritt. Grün: geprüft und abgeschlossen. Aufgaben sind zunächst gleich gewichtet.</p><div class="info">Planentwurf · Zeitraum, Termine und Reihenfolge werden lokal gespeichert. Standardcheckliste: LS4a. Eigene Arbeiten können für alle sieben Segelflugzeuge ergänzt werden.</div></div><div class="top"><h2>Arbeitsbereiche</h2><button class="primary" onclick="openWinter(3)">LS4a-Wartung öffnen →</button></div><div class="stats">${groups.map(g=>`<div class="stat"><span class="eyebrow">LS 4 a</span><h3>${g}</h3><p class="small muted">${expanded().filter(t=>t.group===g).length} Teilaufgaben</p></div>`).join('')}</div>`}
function openWinter(i,scope='winter',year=annualYear()){selected=i;workView={type:'list',i,scope,year};const f=DATA.fleet[i],items=workItems(i,scope,year),wp=workProgress(i,scope,year),sections=[...new Set([...groups,...items.map(t=>t.group)])];showDialog(`${f.name}${f.reg==='Kennzeichen ergänzen'?'':' · '+f.reg}`,scope==='annual'?'Arbeiten im laufenden Jahr / '+year:'Winterwartung / Aufgabenpakete',`${i===3&&scope==='winter'?'<div class="links"><a href="assets/winter-ls4.docx">Originalvorlage herunterladen</a><span>V1.0 · 16.10.2026</span></div>':''}<div class="top"><div><strong>${wp.workedPct}% bearbeitet · ${wp.checkedPct}% geprüft</strong><p class="small muted">${wp.done} von ${wp.total} durchgeführt · ${wp.active} in Arbeit</p></div><button class="primary" onclick="openWorkForm(${i},null,null,'${scope}')">＋ Arbeit hinzufügen</button></div><div class="work-progress-track"><span class="worked-fill" style="width:${wp.workedPct}%"></span><span class="checked-fill" style="width:${wp.checkedPct}%"></span></div>${!items.length?'<div class="info">Noch keine Checkliste hinterlegt. Hier kannst du eigene Arbeiten anlegen.</div>':''}${sections.filter(g=>items.some(t=>t.group===g)).map(g=>`<details open><summary class="sectiontitle">${esc(g)}</summary>${items.filter(t=>t.group===g).map(t=>{const r=task(i,t.key);return `<div class="row"><div class="tasktext"><details><summary>${esc(t.title)}</summary>${t.dueDate?`<p class="small">Termin: ${esc(t.dueDate.split('-').reverse().join('.'))}</p>`:''}<p>${esc(t.text)}</p>${t.sourceIssueId?sourceIssueHTML(i,t.sourceIssueId):''}${t.sourceTaskKey!==null&&t.sourceTaskKey!==undefined?'<span class="badge">Befund aus einer Wartungsarbeit</span>':''}</details><span class="badge ${r.stage==='checked'?'green':r.stage==='done'?'gold':''}">${{open:'Offen',work:'In Arbeit',done:'Durchgeführt · zur Kontrolle',checked:'Geprüft'}[r.stage]}${r.stage==='work'?' · '+(Number(r.percent)||0)+'%':''}</span>${r.by?`<div class="small muted">Durchgeführt: ${esc(r.by)}${r.verifiedBy?' · Geprüft: '+esc(r.verifiedBy):''}</div>`:''}${r.note?`<p>${esc(r.note)}</p>`:''}</div><button onclick="editTask(${esc(JSON.stringify(t.key))})">${r.stage==='checked'?'Ansehen':'Bearbeiten'}</button></div>`}).join('')}</details>`).join('')}`,`<span class="small muted">Automatisch lokal gespeichert</span><button onclick="closeDialog()">Zur Übersicht</button>`)}
function sourceIssueHTML(i,id){const x=(state.issues[i]||[]).find(x=>x.id===id);return x?`<div class="info"><strong>Verknüpfter Mangel</strong><p>${esc(x.text)}</p>${x.location?`<p class="small">${esc(x.location)}</p>`:''}<div class="issue-photos">${(x.photos||[]).map(p=>`<a href="${p.data}" target="_blank" rel="noopener"><img src="${p.data}" alt="Foto des verknüpften Mangels"></a>`).join('')}</div></div>`:'<p class="small muted">Verknüpfte Mängelmeldung nicht verfügbar.</p>'}
function editTask(k){const i=selected,t=findWorkItem(i,k);if(!t)return;workView={type:'edit',i,key:k,scope:t.scope,year:t.year||annualYear()};const r=task(i,k),locked=r.stage==='checked';showDialog(esc(t.title),DATA.fleet[i].name+' / '+esc(t.group),`<p style="white-space:pre-line">${esc(t.text)}</p>${t.dueDate?`<p class="info">Termin: ${esc(t.dueDate.split('-').reverse().join('.'))}</p>`:''}${t.sourceIssueId?sourceIssueHTML(i,t.sourceIssueId):''}<div class="work-date-planning"><label>Geplant für (optional)<input id="workPlanDate" type="date" value="${r.plannedDate||''}" ${locked?'disabled':''}></label><button ${locked?'disabled':''} onclick="$('#workPlanDate').value=nextWeekend().saturday">Für nächstes Wochenende vormerken</button></div><div class="fields"><label>Status<select id="stage" ${locked?'disabled':''} onchange="$('#partialField').hidden=this.value!=='work'"><option value="open">Offen</option><option value="work">In Arbeit</option><option value="done">Durchgeführt · zur Kontrolle</option><option value="checked" ${r.stage==='done'||locked?'':'disabled'}>Geprüft · abgeschlossen</option></select></label><label id="partialField" ${r.stage==='work'?'':'hidden'}>Teilfortschritt dieser Arbeit (%)<input id="taskpercent" type="number" min="0" max="99" value="${Number(r.percent)||0}" ${locked?'disabled':''}></label><label>Person für diese Bestätigung<input id="worker" value="${locked?esc(r.verifiedBy):''}" ${locked?'disabled':''} placeholder="Name"></label></div><label>Bemerkungen / Messwerte<textarea id="tasknote" ${locked?'disabled':''}>${esc(r.note)}</textarea></label><div class="fields"><label>Demo-PIN bei Durchführung oder Prüfung<input id="taskpin" type="password" placeholder="1234" inputmode="numeric" ${locked?'disabled':''}></label></div><p class="small muted">Teilfortschritt kann ohne PIN gespeichert werden. Durchführung und Prüfung werden persönlich bestätigt.</p><button onclick="openWorkForm(${i},null,${esc(JSON.stringify(k))})">＋ Befund / weitere Arbeit hinzufügen</button>`,`<button onclick="openWinter(${i},'${t.scope}',${t.year||annualYear()})">← Aufgaben</button><button class="primary" ${locked?'disabled':''} onclick="saveTask(${esc(JSON.stringify(k))})">Speichern</button>`);$('#stage').value=r.stage}
function saveTask(k){const i=selected,t=findWorkItem(i,k);if(!t)return;const r=task(i,k),stage=$('#stage').value,name=$('#worker').value.trim(),percent=Number($('#taskpercent').value);if(r.stage==='checked')return;if(!['open','work','done','checked'].includes(stage))return;if(stage==='work'&&(!Number.isFinite(percent)||percent<0||percent>99)){toast('Bitte einen Teilfortschritt von 0 bis 99 Prozent angeben.');return}if(['done','checked'].includes(stage)&&(!name||$('#taskpin').value!=='1234')){toast('Zum Abschluss Name und Demo-PIN 1234 eingeben.');return}if(stage==='checked'&&r.stage!=='done')return;const old={...r};r.plannedDate=$('#workPlanDate').value||'';r.stage=stage;r.percent=stage==='work'?Math.round(percent):['done','checked'].includes(stage)?100:0;r.note=$('#tasknote').value;if(stage==='done')r.by=name;if(stage==='checked')r.verifiedBy=name;if(!save()){if(old.plannedDate===undefined)delete r.plannedDate;Object.assign(r,old);return}openWinter(i,t.scope,t.year||annualYear());render();toast(t.scope==='annual'?'Jahresarbeit aktualisiert':'Arbeitsstand gespeichert · Gantt aktualisiert')}
function workFromIssue(k){const x=issues(selected)[k];if(!x)return;if(x.workId){toast('Zu diesem Mangel ist bereits eine Arbeit erfasst.');return}openWorkForm(selected,x)}
function openWorkForm(i=null,issue=null,sourceTaskKey=null,requestedScope=null){workFormReturn=$('#detail').open&&workView?{...workView}:null;const hasAircraft=Number.isInteger(i)&&DATA.fleet[i],originTask=hasAircraft&&sourceTaskKey!==null?findWorkItem(i,sourceTaskKey):null,scope=requestedScope||originTask?.scope||(issue?'annual':workFormReturn?.scope||(mode==='winter'?'winter':'annual'));workDraft={i:hasAircraft?i:scope==='winter'?winterFleet()[0]:0,title:issue?'Befund beheben: '+issue.text.slice(0,90):'',text:issue?issue.text:originTask?'Befund bei „'+originTask.title+'“: ':'',group:'Zusätzliche Arbeiten',issue,sourceTaskKey,scope,year:originTask?.year||workFormReturn?.year||annualYear(),dueDate:''};$('#workContent').innerHTML=`<div class="dhead"><div><div class="eyebrow">${issue?'Aus Mängelmeldung':originTask?'Befund bei Kontrolle':'Neue Arbeit'}</div><h2>Arbeit hinzufügen</h2></div><button aria-label="Schließen" onclick="$('#workDialog').close()">✕</button></div><div class="dbody"><div class="fields"><label>Flugzeug<select onchange="workDraft.i=Number(this.value)" ${hasAircraft?'disabled':''}>${(hasAircraft?[i]:DATA.fleet.map((_,i)=>i)).map(a=>`<option value="${a}" ${a===workDraft.i?'selected':''}>${DATA.fleet[a].name}</option>`).join('')}</select></label><label>Zuordnung<select onchange="workDraft.scope=this.value;$('#workYearField').hidden=this.value!=='annual'"><option value="annual" ${scope==='annual'?'selected':''}>Arbeit im laufenden Jahr</option><option value="winter" ${scope==='winter'?'selected':''}>Winterwartung</option></select></label><label id="workYearField" ${scope==='annual'?'':'hidden'}>Jahr<input type="number" min="2020" max="2100" value="${workDraft.year}" oninput="workDraft.year=Number(this.value)"></label><label>Termin (optional)<input type="date" value="${workDraft.dueDate}" oninput="workDraft.dueDate=this.value"></label><label>Aufgabenpaket<select onchange="workDraft.group=this.value">${[...groups,'Zusätzliche Arbeiten'].map(g=>`<option ${g===workDraft.group?'selected':''}>${g}</option>`).join('')}</select></label></div><label>Titel der Arbeit<input class="work-title-input" value="${esc(workDraft.title)}" placeholder="z. B. Lackschaden ausbessern" oninput="workDraft.title=this.value"></label><label>Beschreibung / Befund<textarea oninput="workDraft.text=this.value">${esc(workDraft.text)}</textarea></label>${issue?'<p class="info">Die Arbeit wird mit dem Mangel und dessen Fotos verknüpft. Die Einstufung des Mangels bleibt bestehen.</p>':''}</div><div class="dfoot"><button onclick="$('#workDialog').close()">Abbrechen</button><button class="primary" onclick="saveCustomWork()">Arbeit anlegen</button></div>`;$('#workDialog').showModal()}
function saveCustomWork(){if(!workDraft?.title.trim()){toast('Bitte einen Titel für die Arbeit eingeben.');return}const d=workDraft;if(!DATA.fleet[d.i]||!['annual','winter'].includes(d.scope)){toast('Bitte eine gültige Zuordnung wählen.');return}if(d.scope==='winter'&&!winterFleet().includes(d.i)){toast('Die Dynamic nimmt nicht an der Winterwartung teil. Bitte eine Jahresarbeit anlegen.');return}if(d.scope==='annual'&&(!Number.isInteger(d.year)||d.year<2020||d.year>2100)){toast('Bitte ein gültiges Jahr eingeben.');return}if(d.dueDate&&d.scope==='annual'&&Number(d.dueDate.slice(0,4))!==d.year){toast('Der Termin muss im gewählten Jahr liegen.');return}if(d.issue?.workId){toast('Zu diesem Mangel gibt es bereits eine Arbeit.');return}const previousIssueId=d.issue?.id;if(d.issue&&!d.issue.id)d.issue.id=newId();const work=makeCustomWork(d.title,d.text,d.group,d.issue?.id||null,d.sourceTaskKey,{scope:d.scope,year:d.year,dueDate:d.dueDate});customWorks(d.i).push(work);if(d.issue)d.issue.workId=work.id;const oldAnnualYear=state.annualYear;if(d.scope==='annual')state.annualYear=d.year;if(!save()){customWorks(d.i).pop();if(oldAnnualYear===undefined)delete state.annualYear;else state.annualYear=oldAnnualYear;if(d.issue){delete d.issue.workId;if(previousIssueId===undefined)delete d.issue.id;else d.issue.id=previousIssueId}return}$('#workDialog').close();if(d.scope==='annual')state.annualYear=d.year;if(workFormReturn?.type==='list')openWinter(workFormReturn.i,workFormReturn.scope||'winter',workFormReturn.year||annualYear());else if(workFormReturn?.type==='edit'){}else if($('#detail').open&&step==='issues')drawDaily();render();toast(d.scope==='annual'?'Arbeit im laufenden Jahr angelegt':'Zusätzliche Winterarbeit angelegt')}
function annualWorkFromIssue(i,k){selected=i;workView=null;workFromIssue(k)}
function openLinkedWork(i,id){selected=i;const key='custom:'+id;if(findWorkItem(i,key))editTask(key);else toast('Die verknüpfte Arbeit wurde nicht gefunden.')}
function openAnnualTask(i,key){selected=i;editTask(key)}
function annualDeadline(t,r){if(r.stage==='checked')return '<span class="badge green">Geprüft abgeschlossen</span>';if(r.stage==='done')return '<span class="badge gold">Durchgeführt · Prüfung offen</span>';if(!t.dueDate)return '<span class="small muted">Ohne festen Termin</span>';const overdue=t.dueDate<today();return `<span class="badge ${overdue?'red':''}">${t.dueDate.split('-').reverse().join('.')}</span>${overdue?'<small>Erledigung noch nicht dokumentiert</small>':''}`}
function renderAnnualWork(){if(!$('#annualWork'))return;const year=annualYear(),openBlockers=DATA.fleet.flatMap((f,i)=>issues(i).map((x,k)=>({i,k,x})).filter(({x})=>impact(x)==='blocking')),items=DATA.fleet.flatMap((f,i)=>workItems(i,'annual',year).map(t=>({i,t,r:task(i,t.key)}))),done=items.filter(({r})=>r.stage==='checked').length;items.sort((a,b)=>(a.r.stage==='checked')-(b.r.stage==='checked')||(a.t.dueDate||'9999').localeCompare(b.t.dueDate||'9999')||a.i-b.i);$('#annualWork').innerHTML=`<div class="top"><div><div class="eyebrow">Flugbetrieb / Arbeiten während des Jahres</div><h2>Was im Jahr noch ansteht</h2><p class="muted">Mängel beheben, laufende Arbeiten und zusätzliche Pflege.</p></div><div class="annual-actions"><label>Jahr<select aria-label="Jahr für laufende Arbeiten" onchange="state.annualYear=Number(this.value);save();renderAnnualWork()">${[year-1,year,year+1].map(y=>`<option ${y===year?'selected':''}>${y}</option>`).join('')}</select></label><button class="primary" onclick="openWorkForm(null,null,null,'annual')">＋ Jahresarbeit hinzufügen</button></div></div>${openBlockers.length?`<div class="annual-blockers"><h3>Flugzeuge unklar · ${openBlockers.length} sperrende Mängel</h3>${openBlockers.map(({i,k,x})=>`<div class="annual-blocker"><div><strong>${DATA.fleet[i].name}</strong><p>${esc(x.text)}</p></div>${x.workId?`<button onclick="openLinkedWork(${i},'${esc(x.workId)}')">Arbeit ansehen →</button>`:`<button onclick="annualWorkFromIssue(${i},${k})">＋ Behebung als Arbeit erfassen</button>`}</div>`).join('')}</div>`:''}<div class="annual-summary"><strong>Zusätzliches Wachsen bis 30. Juni ${year}</strong><span>Für jedes der acht Flugzeuge jährlich separat dokumentiert.</span><span class="badge">${done} / ${items.length} Jahresarbeiten geprüft</span></div><div class="annual-table"><div class="annual-table-head"><span>Flugzeug / Arbeit</span><span>Termin</span><span>Arbeitsstand</span><span></span></div>${items.map(({i,t,r})=>`<div class="annual-work-row"><div><strong>${DATA.fleet[i].name}</strong><p>${esc(t.title)}</p></div><div class="annual-due">${annualDeadline(t,r)}</div><div><span class="badge ${r.stage==='checked'?'green':r.stage==='done'?'gold':''}">${{open:'Offen',work:'In Arbeit · '+(Number(r.percent)||0)+'%',done:'Durchgeführt',checked:'Geprüft'}[r.stage]}</span></div><button onclick="openAnnualTask(${i},${esc(JSON.stringify(t.key))})">${r.stage==='checked'?'Ansehen':'Bearbeiten'}</button></div>`).join('')}</div><p class="small muted">Jahresarbeiten werden unabhängig von der Winterwartung geführt. Das Abschließen einer Arbeit ändert die Einstufung eines verknüpften Mangels nicht automatisch.</p>`}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='acl-technik-testdaten.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function resetData(){if(confirm('Alle lokalen Demo-Eingaben und Testprotokolle zurücksetzen?')){state=initial();save();render()}}
render();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#detail').open)render()});
